import{c as e,Q as r,j as a,m as o}from"./chunks/framework.rWdQudnF.js";const c=JSON.parse('{"title":"架构师-备考 综合知识-软件工程-开发环境与集成架构","description":"","frontmatter":{"title":"架构师-备考 综合知识-软件工程-开发环境与集成架构"},"headers":[],"relativePath":"综合知识/软件工程/开发环境与集成架构.md","filePath":"综合知识/软件工程/开发环境与集成架构.md","lastUpdated":null}'),l={name:"综合知识/软件工程/开发环境与集成架构.md"};function d(n,t,s,i,g,h){return r(),a("div",null,[...t[0]||(t[0]=[o('<h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[x] 软件开发环境集成机制（三部分）</li><li>[x] MVC 架构模式</li><li>[x] EAI 企业应用集成（四种集成方式）</li><li>[x] EJB 三种 Bean</li><li>[x] MDD 模型驱动开发（PIM/PSM）</li><li>[x] AOP 面向方面编程</li><li>[x] 持久化技术框架（MyBatis vs Hibernate）</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="一、软件开发环境集成机制-★" tabindex="-1">一、软件开发环境集成机制 ★ <a class="header-anchor" href="#一、软件开发环境集成机制-★" aria-label="Permalink to &quot;一、软件开发环境集成机制 ★&quot;">​</a></h3><blockquote><p>🎯 一句话结论：开发环境集成 = <strong>环境信息库</strong>（存储共享）+ <strong>过程控制与消息服务器</strong>（过程集成基础）+ <strong>环境用户界面</strong>（统一一致性）。</p></blockquote><table tabindex="0"><thead><tr><th style="text-align:left;">部分</th><th>功能</th><th>关键词</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>环境信息库</strong></td><td>存储与系统开发有关的信息，支持信息交流与共享</td><td>存储、共享</td></tr><tr><td style="text-align:left;"><strong>过程控制与消息服务器</strong></td><td>实现过程集成和控制集成的基础</td><td>过程集成、控制集成</td></tr><tr><td style="text-align:left;"><strong>环境用户界面</strong></td><td>统一性和一致性是开发环境的重要特征</td><td>统一界面、一致性</td></tr></tbody></table><blockquote><p>记忆技巧：<strong>库存消息，统一界</strong> — 信息库(存储) → 过程控制消息 → 统一用户界面</p></blockquote><hr><h3 id="二、mvc-架构模式-★" tabindex="-1">二、MVC 架构模式 ★ <a class="header-anchor" href="#二、mvc-架构模式-★" aria-label="Permalink to &quot;二、MVC 架构模式 ★&quot;">​</a></h3><blockquote><p>🎯 一句话结论：<strong>M=数据模型（Model），V=视图展示（View），C=控制器（Controller）将用户动作转为模型操作。</strong></p></blockquote><table tabindex="0"><thead><tr><th style="text-align:left;">元素</th><th>职责</th><th>J2EE 对应</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Model</strong></td><td>待展示的对象，业务数据和逻辑</td><td>JavaBean、Service、DAO</td></tr><tr><td style="text-align:left;"><strong>View</strong></td><td>展示模型、接收用户输入，不做业务处理</td><td><strong>JSP</strong></td></tr><tr><td style="text-align:left;"><strong>Controller</strong></td><td>将用户动作转成针对 Model 的操作</td><td><strong>Servlet</strong></td></tr></tbody></table><p><strong>MVC 分层对应：</strong> JSP(View) → Servlet(Controller) → Service(业务逻辑) → JavaBean(Model) → DAO(数据访问)</p><hr><h3 id="三、eai-企业应用集成-★" tabindex="-1">三、EAI 企业应用集成 ★ <a class="header-anchor" href="#三、eai-企业应用集成-★" aria-label="Permalink to &quot;三、EAI 企业应用集成 ★&quot;">​</a></h3><blockquote><p>🎯 一句话结论：集成方式从表到里依次是 <strong>界面集成（外观统一）→ 数据集成（共享数据）→ 过程集成（跨系统流程）→ 面向服务集成（SOA/WebService）</strong>。</p></blockquote><table tabindex="0"><thead><tr><th style="text-align:left;">集成方式</th><th>说明</th><th>特点</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>界面集成</strong></td><td>在用户使用角度产生&quot;整体&quot;感觉</td><td>最表层，统一入口</td></tr><tr><td style="text-align:left;"><strong>数据集成</strong></td><td>企业之间的信息共享能力</td><td>数据层面互通</td></tr><tr><td style="text-align:left;"><strong>过程集成</strong></td><td>提供企业之间的信息共享能力</td><td>跨系统业务流程</td></tr><tr><td style="text-align:left;"><strong>面向服务集成</strong></td><td>基于 SOA 和 Web Service</td><td>最灵活，松耦合</td></tr></tbody></table><blockquote><p>⚠️ 关键辨析：基于 SOA/WebService 的模式是<strong>面向服务的集成</strong>，不是面向过程也不是面向信息。</p></blockquote><hr><h3 id="四、ejb-三种-bean-★" tabindex="-1">四、EJB 三种 Bean ★ <a class="header-anchor" href="#四、ejb-三种-bean-★" aria-label="Permalink to &quot;四、EJB 三种 Bean ★&quot;">​</a></h3><blockquote><p>🎯 一句话结论：<strong>Session Bean 管会话（短暂），Entity Bean 管数据（持久），Message-Driven Bean 管异步消息。</strong></p></blockquote><table tabindex="0"><thead><tr><th style="text-align:left;">Bean 类型</th><th>职责</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Session Bean</strong></td><td>维护短暂会话，客户端执行完成后数据消失</td></tr><tr><td style="text-align:left;"><strong>Entity Bean</strong></td><td>维护一行持久稳固的数据，服务结束后底层服务负责存储</td></tr><tr><td style="text-align:left;"><strong>Message-Driven Bean</strong></td><td>结合 Session Bean 和 JMS，允许<strong>异步接收消息</strong></td></tr></tbody></table><p><strong>有状态 vs 无状态构件辨析：</strong></p><ul><li><strong>有状态</strong>（上下文依赖）：身份认证、资源发布、在线编辑</li><li><strong>无状态</strong>（独立无上下文）：资源检索、统计分析</li></ul><hr><h3 id="五、mdd-模型驱动开发" tabindex="-1">五、MDD 模型驱动开发 <a class="header-anchor" href="#五、mdd-模型驱动开发" aria-label="Permalink to &quot;五、MDD 模型驱动开发&quot;">​</a></h3><blockquote><p>🎯 一句话结论：PIM（平台无关模型）在不涉及实现的情况下建模，PSM（平台相关模型）绑定具体平台。</p></blockquote><table tabindex="0"><thead><tr><th style="text-align:left;">模型</th><th>说明</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>CIM</strong>（计算无关模型）</td><td>业务视角，不涉及系统</td></tr><tr><td style="text-align:left;"><strong>PIM</strong>（平台无关模型）</td><td>系统功能逻辑，<strong>不涉及实现</strong></td></tr><tr><td style="text-align:left;"><strong>PSM</strong>（平台相关模型）</td><td>绑定具体技术平台</td></tr></tbody></table><hr><h3 id="六、aop-面向方面编程" tabindex="-1">六、AOP 面向方面编程 <a class="header-anchor" href="#六、aop-面向方面编程" aria-label="Permalink to &quot;六、AOP 面向方面编程&quot;">​</a></h3><blockquote><p>🎯 一句话结论：将<strong>横切关注点</strong>（日志、安全、事务、持久化）从核心业务逻辑中分离，封装到独立**方面（Aspect）**模块中。</p></blockquote><ul><li>核心概念：横切关注点、方面（Aspect）、切入点（Pointcut）、通知（Advice）</li><li>解决的问题：通用功能代码分散/纠缠，不利于模块化和维护</li></ul><hr><h3 id="七、持久化框架-★" tabindex="-1">七、持久化框架 ★ <a class="header-anchor" href="#七、持久化框架-★" aria-label="Permalink to &quot;七、持久化框架 ★&quot;">​</a></h3><table tabindex="0"><thead><tr><th>框架</th><th>特点</th><th style="text-align:center;">是否需要手写 SQL</th></tr></thead><tbody><tr><td><strong>MyBatis</strong></td><td>半自动，灵活</td><td style="text-align:center;">✅ 需要</td></tr><tr><td><strong>Hibernate</strong></td><td><strong>全自动 ORM</strong>，对象关系映射</td><td style="text-align:center;">❌ 不需要</td></tr><tr><td><strong>JDO</strong></td><td>Java 数据对象标准</td><td style="text-align:center;">❌</td></tr><tr><td><strong>Entity Framework</strong></td><td>.NET ORM 框架</td><td style="text-align:center;">❌</td></tr></tbody></table>',34)])])}const x=e(l,[["render",d]]);export{c as __pageData,x as default};
